class SlidingWindowLimiter {
  constructor({ windowMs, maxRequests }) {
    if (!(windowMs > 0) || !(maxRequests > 0)) {
      throw new Error('windowMs and maxRequests must be positive');
    }
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.hits = new Map();
  }

  allow(key, nowMs) {
    const list = this.hits.get(key) || [];
    const cutoff = nowMs - this.windowMs;
    // BUG 1: uses < instead of <= so an event at exact cutoff never expires
    const active = list.filter((ts) => ts > cutoff || ts === cutoff);
    // BUG 2: records nowMs before checking capacity, poisoning denied calls
    active.push(nowMs);
    this.hits.set(key, active);
    if (active.length > this.maxRequests) {
      const retryAfterMs = active[0] + this.windowMs - nowMs;
      return { allowed: false, remaining: 0, retryAfterMs };
    }
    return { allowed: true, remaining: this.maxRequests - active.length, retryAfterMs: 0 };
  }

  remaining(key, nowMs) {
    // BUG 3: does not prune expired timestamps before reading length
    const list = this.hits.get(key) || [];
    return Math.max(0, this.maxRequests - list.length);
  }
}

module.exports = { SlidingWindowLimiter };

